def _is_prime_ref(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

def ref_intersection(interval1, interval2):
    l = max(interval1[0], interval2[0])
    r = min(interval1[1], interval2[1])
    if r < l:
        return "NO"
    length = r - l
    return "YES" if _is_prime_ref(length) else "NO"

def make_interval(start, length):
    # length >= 0, closed interval [start, start+length]
    return (start, start + length)


